import { sql } from 'drizzle-orm';
import {
  type AnyPgColumn,
  bigint,
  boolean,
  check,
  customType,
  date,
  doublePrecision,
  foreignKey,
  index,
  inet,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';
import { uuidv7 } from 'uuidv7';

/**
 * The metadata schema (`public`), managed by Drizzle migrations in ../../drizzle.
 *
 * - Ids are UUIDv7, generated by the app (ADR-001), so they sort by creation time.
 * - Users and sessions are global. Every other table is tenant-owned: it carries
 *   `workspace_id NOT NULL`, and children point at their parent through a composite FK that
 *   includes the workspace, so a row can't reference a parent in another workspace (ADR-002).
 *   Every table except users and sessions has `FORCE ROW LEVEL SECURITY` with a tenant policy
 *   on `app.workspace_id`. Policies, grants and the `authz_resolve` function aren't expressible
 *   in Drizzle; they live in the hand-written migration drizzle/0003_rls.sql (see src/authz).
 * - Physical record tables live in per-base `b_<uuid>` schemas and are never managed here
 *   (ADR-001); drizzle.config.ts filters to `public`.
 */

const id = () =>
  uuid('id')
    .primaryKey()
    .$defaultFn(() => uuidv7());

const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());
const deletedAt = () => timestamp('deleted_at', { withTimezone: true });

const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => 'bytea',
});

/** A 64-bit transaction id (`xid8`), as text: it outgrows a JS number. */
const xid8 = customType<{ data: string; driverData: string }>({
  dataType: () => 'xid8',
});

/** Workspace roles. Must match USER_ROLES in @openrows/shared (a unit test checks). */
export const WORKSPACE_ROLES = ['owner', 'creator', 'editor', 'commenter', 'read_only'] as const;
/** Base-level override roles. Must match BASE_ROLES in @openrows/shared (a unit test checks). */
export const BASE_ROLES = ['creator', 'editor', 'commenter', 'read_only'] as const;
/** Interface-only roles. Must match INTERFACE_ROLES in @openrows/shared (a unit test checks). */
export const INTERFACE_ROLES = ['editor', 'read_only'] as const;

const roleCheck = (name: string, roles: readonly string[]) =>
  check(name, sql.raw(`role IN (${roles.map((r) => `'${r}'`).join(', ')})`));

// ============================================================================
// Global: users and sessions (Keycloak OIDC, ADR-006)
// ============================================================================

export const users = pgTable(
  'users',
  {
    id: id(),
    oidcIssuer: text('oidc_issuer').notNull(),
    oidcSubject: text('oidc_subject').notNull(),
    email: text('email'),
    emailVerified: boolean('email_verified').notNull().default(false),
    name: text('name'),
    avatarUrl: text('avatar_url'),
    // Set only from the CLI or OPENROWS_SYSTEM_ADMINS, never derived from ownership (ADR-002).
    isSystemAdmin: boolean('is_system_admin').notNull().default(false),
    // Which notifications are emailed: all, mentions only, or none.
    notificationEmail: text('notification_email', { enum: ['all', 'mentions', 'none'] })
      .notNull()
      .default('all'),
    // When they are emailed: one email per record as they come, or hourly/daily digests.
    notificationFrequency: text('notification_frequency', {
      enum: ['immediately', 'hourly', 'daily'],
    })
      .notNull()
      .default('immediately'),
    // Created on first sign-in. Set once, so a deleted or renamed one isn't recreated.
    personalWorkspaceId: uuid('personal_workspace_id').references(
      (): AnyPgColumn => workspaces.id,
      { onDelete: 'set null' }
    ),
    /**
     * The user asked to delete their account: they can't sign in any more, and the worker's
     * `purge.deleted` job deletes the row and everything personal within the hour (the row is
     * gone afterwards, so this is only ever seen in between).
     */
    deletedAt: deletedAt(),
    /**
     * A system admin suspended the account (the ops console): its sessions end, sign-in and
     * its personal access tokens are refused until it is lifted.
     */
    suspendedAt: timestamp('suspended_at', { withTimezone: true }),
    suspendedReason: text('suspended_reason'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique('users_oidc_identity_unique').on(t.oidcIssuer, t.oidcSubject),
    check(
      'users_notification_email_check',
      sql`${t.notificationEmail} IN ('all', 'mentions', 'none')`
    ),
    check(
      'users_notification_frequency_check',
      sql`${t.notificationFrequency} IN ('immediately', 'hourly', 'daily')`
    ),
    // Invitations match by (verified) email, case-insensitively.
    index('users_email_idx').on(sql`lower(${t.email})`),
  ]
);

/**
 * Server-side sessions (backend-for-frontend). The cookie holds a random 256-bit token; only
 * its SHA-256 is stored, so a database leak doesn't leak live sessions. OIDC tokens are stored
 * as ciphertext (AES-256-GCM, src/auth/crypto.ts) and never reach the browser.
 */
export const sessions = pgTable(
  'sessions',
  {
    idHash: text('id_hash').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    // Absolute expiry; idle expiry is computed from last_seen_at (ADR-006: 7 and 30 days).
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    lastSeenAt: timestamp('last_seen_at', { withTimezone: true }).notNull().defaultNow(),
    // The provider's `sid` claim, so back-channel logout can find the session.
    oidcSid: text('oidc_sid'),
    refreshTokenEnc: bytea('refresh_token_enc'),
    idTokenEnc: bytea('id_token_enc'),
    // When the refresh token was last used; the server refreshes every few minutes while the
    // session is in use, so a user disabled in the provider is signed out quickly.
    tokensRefreshedAt: timestamp('tokens_refreshed_at', { withTimezone: true })
      .notNull()
      .defaultNow(),
    userAgent: text('user_agent'),
    ip: inet('ip'),
    /**
     * When the user last entered their credentials at the provider (the ID token's `auth_time`),
     * for actions that need a recent sign-in (deleting the account).
     */
    authenticatedAt: timestamp('authenticated_at', { withTimezone: true }),
    /**
     * A system admin's session viewing the app as this user, read-only, until
     * `impersonation_expires_at`. Set and cleared only by the ops console (hosted edition).
     */
    impersonatedUserId: uuid('impersonated_user_id').references(() => users.id, {
      onDelete: 'set null',
    }),
    impersonationExpiresAt: timestamp('impersonation_expires_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    index('sessions_user_id_idx').on(t.userId),
    index('sessions_oidc_sid_idx').on(t.oidcSid),
    index('sessions_expires_at_idx').on(t.expiresAt),
  ]
);

/**
 * Personal access tokens: `Authorization: Bearer or_pat_<publicId>_<secret>`. Owned by a
 * user, not a tenant: RLS shows a user only their own (0040_personal_access_tokens_rls.sql), and
 * bearer auth looks them up by public id through the SECURITY DEFINER `pat_lookup`. The grants
 * name workspaces and bases; the role in them is read live on every request, never stored.
 */
export const personalAccessTokens = pgTable(
  'personal_access_tokens',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    /** The greppable public part after `or_pat_`. */
    publicId: text('public_id').notNull(),
    /** SHA-256 of the 32-byte secret, hex. The secret itself is shown once and never stored. */
    secretHash: text('secret_hash').notNull(),
    scopes: text('scopes').array().notNull(),
    /** Every current and future base of these workspaces. */
    workspaceIds: uuid('workspace_ids').array().notNull().default(sql`'{}'::uuid[]`),
    /** These bases only. */
    baseIds: uuid('base_ids').array().notNull().default(sql`'{}'::uuid[]`),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    lastUsedAt: timestamp('last_used_at', { withTimezone: true }),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    unique('personal_access_tokens_public_id_unique').on(t.publicId),
    index('personal_access_tokens_user_id_idx').on(t.userId),
  ]
);

/**
 * Requests per personal access token and UTC day, shown in the token list. Counted by the
 * SECURITY DEFINER `pat_use` on every bearer request; RLS shows a user only their own tokens'
 * (0042_api_rate_limits_rls.sql). Kept 90 days (`pat_usage_prune`).
 */
export const personalAccessTokenUsage = pgTable(
  'personal_access_token_usage',
  {
    tokenId: uuid('token_id')
      .notNull()
      .references(() => personalAccessTokens.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    day: date('day', { mode: 'string' }).notNull(),
    requests: integer('requests').notNull().default(0),
  },
  (t) => [
    primaryKey({ columns: [t.tokenId, t.day] }),
    index('personal_access_token_usage_user_id_idx').on(t.userId),
  ]
);

/**
 * OAuth apps: integrations a user registered to ask other people for access through the
 * authorization code flow with PKCE. Owned by the user who registered them (RLS on
 * `app.user_id`, 0108_oauth_rls.sql); the consent screen and the token endpoint read one by its
 * client id through the SECURITY DEFINER `oauth_app_lookup`. Deleting one (`deleted_at`) ends
 * every authorization and token of it at once.
 */
export const oauthApps = pgTable(
  'oauth_apps',
  {
    id: id(),
    ownerId: uuid('owner_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    description: text('description').notNull().default(''),
    homepageUrl: text('homepage_url'),
    /** Public: `or_app_<20 base32>`. */
    clientId: text('client_id').notNull(),
    /** SHA-256 of the client secret, hex. The secret is shown once (on creation and rotation). */
    secretHash: text('secret_hash').notNull(),
    /** Exact redirect URIs the app may send people back to. */
    redirectUris: text('redirect_uris').array().notNull(),
    createdAt: createdAt(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
  },
  (t) => [
    unique('oauth_apps_client_id_unique').on(t.clientId),
    index('oauth_apps_owner_id_idx').on(t.ownerId),
  ]
);

/**
 * A person's consent to an OAuth app: the scopes it asked for and the workspaces or bases
 * they picked, exactly like a personal access token's. One live authorization per person and app
 * (consenting again replaces its scopes and grants); revoking it (Settings → Integrations) ends
 * every token issued under it. The access is still the person's live role ∩ scopes ∩ grants.
 */
export const oauthAuthorizations = pgTable(
  'oauth_authorizations',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    appId: uuid('app_id')
      .notNull()
      .references(() => oauthApps.id, { onDelete: 'cascade' }),
    scopes: text('scopes').array().notNull(),
    workspaceIds: uuid('workspace_ids').array().notNull().default(sql`'{}'::uuid[]`),
    baseIds: uuid('base_ids').array().notNull().default(sql`'{}'::uuid[]`),
    createdAt: createdAt(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
    lastUsedAt: timestamp('last_used_at', { withTimezone: true }),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
  },
  (t) => [
    uniqueIndex('oauth_authorizations_live_unique')
      .on(t.userId, t.appId)
      .where(sql`${t.revokedAt} IS NULL`),
    index('oauth_authorizations_app_id_idx').on(t.appId),
  ]
);

/**
 * Authorization codes: one use, ten minutes, bound to the app, the redirect URI and the
 * PKCE challenge (S256). Only the SHA-256 is stored; `oauth_code_lookup` finds one before the
 * person is known, and its single use is the conditional `used_at` update in their scope.
 */
export const oauthCodes = pgTable(
  'oauth_codes',
  {
    id: id(),
    codeHash: text('code_hash').notNull(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    authorizationId: uuid('authorization_id')
      .notNull()
      .references(() => oauthAuthorizations.id, { onDelete: 'cascade' }),
    redirectUri: text('redirect_uri').notNull(),
    codeChallenge: text('code_challenge').notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    usedAt: timestamp('used_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    unique('oauth_codes_code_hash_unique').on(t.codeHash),
    index('oauth_codes_authorization_id_idx').on(t.authorizationId),
  ]
);

/**
 * OAuth access tokens (`or_oat_…`, an hour) and refresh tokens (`or_ort_…`, 60 days, one use:
 * each refresh rotates the pair, and a refresh token used twice revokes the authorization)
 * . Stored as the SHA-256 of the secret, found by the public id through
 * `oauth_token_lookup` (with the authorization's scopes and grants).
 */
export const oauthTokens = pgTable(
  'oauth_tokens',
  {
    id: id(),
    authorizationId: uuid('authorization_id')
      .notNull()
      .references(() => oauthAuthorizations.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    kind: text('kind', { enum: ['access', 'refresh'] }).notNull(),
    publicId: text('public_id').notNull(),
    secretHash: text('secret_hash').notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    /** A refresh token's one use (rotation), or an access token's revocation. */
    usedAt: timestamp('used_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    unique('oauth_tokens_public_id_unique').on(t.publicId),
    index('oauth_tokens_authorization_id_idx').on(t.authorizationId),
    index('oauth_tokens_expires_at_idx').on(t.expiresAt),
    check('oauth_tokens_kind_check', sql`${t.kind} IN ('access', 'refresh')`),
  ]
);

/**
 * The API's token buckets, shared by every server instance: `key` is `base:<id>`,
 * `token:<id>` or `user:<id>`, `tokens` the level at `updated_at`. UNLOGGED (0042: losing them in
 * a crash only refills the buckets) and reachable only through the SECURITY DEFINER
 * `rate_limit_take` and `rate_limit_prune`; the app role has no rights on the table.
 */
export const rateLimitBuckets = pgTable('rate_limit_buckets', {
  key: text('key').primaryKey(),
  tokens: doublePrecision('tokens').notNull(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull(),
});

/**
 * Outbound concurrency slots: one row per (key, slot) held by a running job, `key`
 * `outbound:<workspace id>`. A job takes a free or expired slot below its workspace's cap before
 * its outbound work and gives it back after; a crashed worker's slot expires. UNLOGGED (0067)
 * and reachable only through the SECURITY DEFINER `outbound_lease_take`/`_release`/`_prune`.
 */
export const outboundLeases = pgTable(
  'outbound_leases',
  {
    key: text('key').notNull(),
    slot: integer('slot').notNull(),
    holder: text('holder').notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  },
  (t) => [primaryKey({ columns: [t.key, t.slot] })]
);

// ============================================================================
// Tenant-owned metadata (ADR-001, ADR-002)
// ============================================================================

export const workspaces = pgTable('workspaces', {
  id: id(),
  name: text('name').notNull(),
  // The Postgres cluster that holds this workspace's data (ADR-002 §8).
  dbCluster: text('db_cluster').notNull().default('default'),
  /** How long base snapshots are kept; plans gate it in M5. */
  snapshotRetentionDays: integer('snapshot_retention_days').notNull().default(30),
  /**
   * The hosted plan's id in the hosted catalog; null: the edition's default plan. The OSS
   * edition ignores it. With `plan_overrides` (`planOverridesSchema`: limits and features set by
   * system operators), written only through the SECURITY DEFINER `workspace_plan_set`: the app
   * role may not UPDATE these two columns (0068_usage_counters_rls.sql), so no route can.
   */
  plan: text('plan'),
  planOverrides: jsonb('plan_overrides').notNull().default({}),
  /**
   * A system admin suspended the workspace: members keep reading, nothing changes (403
   * WORKSPACE_SUSPENDED), share links and public forms stop resolving. Written only through the
   * SECURITY DEFINER `workspace_suspend_set` (the app role can't UPDATE these columns).
   */
  suspendedAt: timestamp('suspended_at', { withTimezone: true }),
  suspendedReason: text('suspended_reason'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
  deletedAt: deletedAt(),
});

export const workspaceMembers = pgTable(
  'workspace_members',
  {
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    role: text('role', { enum: WORKSPACE_ROLES }).notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    primaryKey({ columns: [t.workspaceId, t.userId] }),
    index('workspace_members_user_id_idx').on(t.userId),
    roleCheck('workspace_members_role_check', WORKSPACE_ROLES),
  ]
);

/**
 * Invitations to a workspace, or to one of its bases (`base_id` set: accepting adds a
 * `base_members` row, never a workspace membership, and the role is a base role). The emailed
 * token is random (256 bits) and only its SHA-256 is stored, like sessions. Accepting needs a
 * signed-in user whose verified email matches `email` (stored lowercased). At most one pending
 * (not accepted, not revoked) invitation per address and workspace, and per address and base;
 * inviting again rotates its token.
 */
export const workspaceInvitations = pgTable(
  'workspace_invitations',
  {
    id: id(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    /** Null for a workspace invitation. */
    baseId: uuid('base_id'),
    /**
     * An interface invitation (with its `base_id`): the invitee gets this interface only
     * (`interface_members`), with an interface role.
     */
    interfaceId: uuid('interface_id'),
    email: text('email').notNull(),
    role: text('role', { enum: WORKSPACE_ROLES }).notNull(),
    tokenHash: text('token_hash').notNull(),
    invitedBy: uuid('invited_by').references(() => users.id, { onDelete: 'set null' }),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    sentAt: timestamp('sent_at', { withTimezone: true }).notNull().defaultNow(),
    acceptedAt: timestamp('accepted_at', { withTimezone: true }),
    acceptedBy: uuid('accepted_by').references(() => users.id, { onDelete: 'set null' }),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique('workspace_invitations_token_hash_unique').on(t.tokenHash),
    uniqueIndex('workspace_invitations_pending_email_idx')
      .on(t.workspaceId, t.email)
      .where(sql`${t.acceptedAt} IS NULL AND ${t.revokedAt} IS NULL AND ${t.baseId} IS NULL`),
    uniqueIndex('workspace_invitations_pending_base_email_idx')
      .on(t.baseId, t.email)
      .where(
        sql`${t.acceptedAt} IS NULL AND ${t.revokedAt} IS NULL AND ${t.baseId} IS NOT NULL AND ${t.interfaceId} IS NULL`
      ),
    uniqueIndex('workspace_invitations_pending_interface_email_idx')
      .on(t.interfaceId, t.email)
      .where(
        sql`${t.acceptedAt} IS NULL AND ${t.revokedAt} IS NULL AND ${t.interfaceId} IS NOT NULL`
      ),
    foreignKey({
      name: 'workspace_invitations_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
    foreignKey({
      name: 'workspace_invitations_interface_fk',
      columns: [t.workspaceId, t.interfaceId],
      foreignColumns: [interfaces.workspaceId, interfaces.id],
    }).onDelete('cascade'),
    roleCheck('workspace_invitations_role_check', WORKSPACE_ROLES),
    check(
      'workspace_invitations_base_role_check',
      sql.raw(`base_id IS NULL OR role IN (${BASE_ROLES.map((r) => `'${r}'`).join(', ')})`)
    ),
    check(
      'workspace_invitations_interface_role_check',
      sql.raw(
        `interface_id IS NULL OR (base_id IS NOT NULL AND role IN (${INTERFACE_ROLES.map((r) => `'${r}'`).join(', ')}))`
      )
    ),
  ]
);

export const bases = pgTable(
  'bases',
  {
    id: id(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    description: text('description'),
    icon: text('icon'),
    color: text('color'),
    // Physical schema for this base's record tables: b_<uuid hex> (ADR-001). Never re-derived.
    dbSchema: text('db_schema').notNull().unique(),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: deletedAt(),
    deletedBy: uuid('deleted_by').references(() => users.id, { onDelete: 'set null' }),
  },
  (t) => [
    unique('bases_workspace_id_id_unique').on(t.workspaceId, t.id),
    index('bases_workspace_id_idx').on(t.workspaceId),
  ]
);

/**
 * Base-level role overrides. For resources in the base, the override replaces the user's
 * workspace role (it may raise or lower it), except that workspace owners stay owners. A user
 * with an override but no workspace membership is a base-only collaborator.
 */
export const baseMembers = pgTable(
  'base_members',
  {
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    role: text('role', { enum: BASE_ROLES }).notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    primaryKey({ columns: [t.baseId, t.userId] }),
    index('base_members_user_id_idx').on(t.userId),
    foreignKey({
      name: 'base_members_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
    roleCheck('base_members_role_check', BASE_ROLES),
  ]
);

export const tables = pgTable(
  'tables',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    name: text('name').notNull(),
    description: text('description'),
    icon: text('icon'),
    position: doublePrecision('position').notNull().default(0),
    // Physical location: "<db_schema>"."t_<uuid hex>" (ADR-001). Never re-derived.
    dbSchema: text('db_schema').notNull(),
    dbTable: text('db_table').notNull(),
    // Bumped by every DDL change, so caches and clients can detect schema changes.
    schemaVersion: integer('schema_version').notNull().default(0),
    /** Who may add, delete and edit records: `tablePermissionsSchema`, `{}` = defaults. */
    permissions: jsonb('permissions').notNull().default({}),
    /** Synced from another table or view (`table_syncs`): records come only from the sync. */
    synced: boolean('synced').notNull().default(false),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: deletedAt(),
    deletedBy: uuid('deleted_by').references(() => users.id, { onDelete: 'set null' }),
  },
  (t) => [
    unique('tables_workspace_id_id_unique').on(t.workspaceId, t.id),
    unique('tables_db_location_unique').on(t.dbSchema, t.dbTable),
    index('tables_base_id_idx').on(t.baseId),
    foreignKey({
      name: 'tables_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
  ]
);

export const fields = pgTable(
  'fields',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    tableId: uuid('table_id').notNull(),
    name: text('name').notNull(),
    description: text('description'),
    // Validated against the field-type registry in @openrows/shared (M1), not by the database.
    type: text('type').notNull(),
    // Physical column: f_<uuid hex> (ADR-001). Repointed by online type changes.
    dbColumn: text('db_column').notNull(),
    isPrimary: boolean('is_primary').notNull().default(false),
    position: doublePrecision('position').notNull().default(0),
    config: jsonb('config').notNull().default({}),
    /** Who may edit the field's cells: `fieldPermissionsSchema`, `{}` = the default. */
    permissions: jsonb('permissions').notNull().default({}),
    /** Copied from a sync's source: read-only, written only by the sync. */
    synced: boolean('synced').notNull().default(false),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    // Soft delete (trash); the column is dropped when the trash is emptied (ADR-001).
    deletedAt: deletedAt(),
    deletedBy: uuid('deleted_by').references(() => users.id, { onDelete: 'set null' }),
    /**
     * The field or table whose deletion took this one to the trash: a link's inverse goes
     * with it, and a deleted table takes the inverse fields of its links. Such a field comes back
     * with that field or table, never on its own. No foreign key: either may be purged first.
     */
    trashedWith: uuid('trashed_with'),
    /**
     * Set while a computed field waits for a background recompute: a write made more of
     * its cells stale than the request recomputes. The worker clears it when it's done.
     */
    recomputeRequestedAt: timestamp('recompute_requested_at', { withTimezone: true }),
  },
  (t) => [
    unique('fields_workspace_id_id_unique').on(t.workspaceId, t.id),
    unique('fields_table_db_column_unique').on(t.tableId, t.dbColumn),
    uniqueIndex('fields_one_primary_per_table')
      .on(t.tableId)
      .where(sql`${t.isPrimary} AND ${t.deletedAt} IS NULL`),
    index('fields_table_id_idx').on(t.tableId),
    foreignKey({
      name: 'fields_table_fk',
      columns: [t.workspaceId, t.tableId],
      foreignColumns: [tables.workspaceId, tables.id],
    }).onDelete('cascade'),
  ]
);

/** Sidebar sections (folders) of a table's views. */
export const viewSections = pgTable(
  'view_sections',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    tableId: uuid('table_id').notNull(),
    name: text('name').notNull(),
    position: doublePrecision('position').notNull().default(0),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique('view_sections_workspace_id_id_unique').on(t.workspaceId, t.id),
    index('view_sections_table_id_idx').on(t.tableId),
    foreignKey({
      name: 'view_sections_table_fk',
      columns: [t.workspaceId, t.tableId],
      foreignColumns: [tables.workspaceId, tables.id],
    }).onDelete('cascade'),
  ]
);

export const views = pgTable(
  'views',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    tableId: uuid('table_id').notNull(),
    name: text('name').notNull(),
    // Validated against VIEW_TYPES in @openrows/shared, not by the database.
    type: text('type').notNull().default('grid'),
    position: doublePrecision('position').notNull().default(0),
    // Filters, sorts, groups, hidden fields and column widths. Typed by shared Zod (M1).
    config: jsonb('config').notNull().default({}),
    // Personal views are listed and resolved only for created_by (authz_resolve).
    personal: boolean('personal').notNull().default(false),
    // Only creators and owners change a locked view's configuration.
    locked: boolean('locked').notNull().default(false),
    // The service keeps it to a section of the same table.
    sectionId: uuid('section_id').references(() => viewSections.id, { onDelete: 'set null' }),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: deletedAt(),
    deletedBy: uuid('deleted_by').references(() => users.id, { onDelete: 'set null' }),
  },
  (t) => [
    unique('views_workspace_id_id_unique').on(t.workspaceId, t.id),
    index('views_section_id_idx').on(t.sectionId),
    index('views_table_id_idx').on(t.tableId),
    foreignKey({
      name: 'views_table_fk',
      columns: [t.workspaceId, t.tableId],
      foreignColumns: [tables.workspaceId, tables.id],
    }).onDelete('cascade'),
  ]
);

/**
 * A view's manual record order: kanban cards dragged within or between stacks. Records
 * live in per-base tables (ADR-001), so `record_id` has no foreign key; rows of purged records
 * are ignored by the left lookup. Records without a row sort after the positioned ones, oldest
 * first. Positions are spaced by 1024 when a view's order is (re)numbered.
 */
export const viewRecordPositions = pgTable(
  'view_record_positions',
  {
    workspaceId: uuid('workspace_id').notNull(),
    viewId: uuid('view_id').notNull(),
    recordId: uuid('record_id').notNull(),
    position: doublePrecision('position').notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.viewId, t.recordId] }),
    index('view_record_positions_workspace_id_idx').on(t.workspaceId),
    foreignKey({
      name: 'view_record_positions_view_fk',
      columns: [t.workspaceId, t.viewId],
      foreignColumns: [views.workspaceId, views.id],
    }).onDelete('cascade'),
  ]
);

/**
 * The transactional outbox (ADR-003): every schema and data change writes one row in the same
 * transaction, and `pg_notify('outbox', <base id>)` wakes listeners on commit. Consumers
 * (realtime fan-out, webhooks) come later; ids order events per base.
 */
export const outbox = pgTable(
  'outbox',
  {
    id: bigint('id', { mode: 'number' }).primaryKey().generatedAlwaysAsIdentity(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    baseId: uuid('base_id'),
    tableId: uuid('table_id'),
    kind: text('kind').notNull(),
    payload: jsonb('payload').notNull().default({}),
    actorId: uuid('actor_id').references(() => users.id, { onDelete: 'set null' }),
    clientOpId: text('client_op_id'),
    /**
     * The writing transaction. The outbox relay reads past a (txid, id) cursor and only
     * rows whose transaction is older than every one still running, so a late commit holding a
     * lower id is never skipped. Null on rows written before the column existed.
     */
    txid: xid8('txid').default(sql`pg_current_xact_id()`),
    /**
     * The automation run whose transaction wrote the event, and its depth: set by the run
     * (`app.automation_id`/`app.automation_depth`, transaction-local), so every event of its
     * writes carries them, recomputes and the linked side included. Null for anything else.
     */
    automationId: uuid('automation_id').default(
      sql`nullif(current_setting('app.automation_id', true), '')::uuid`
    ),
    automationDepth: smallint('automation_depth').default(
      sql`nullif(current_setting('app.automation_depth', true), '')::smallint`
    ),
    createdAt: createdAt(),
  },
  (t) => [
    index('outbox_base_id_id_idx').on(t.baseId, t.id),
    index('outbox_txid_id_idx').on(t.txid, t.id),
  ]
);

/**
 * The outbox relay's cursor (ADR-004): one row, the (txid, id) of the last outbox row the
 * relay handed to subscribers. Reachable only through the SECURITY DEFINER `outbox_relay_next`
 * and `outbox_relay_advance`; the app role has no rights on the table.
 */
export const outboxRelayCursor = pgTable(
  'outbox_relay_cursor',
  {
    id: smallint('id').primaryKey().default(1),
    txid: xid8('txid').notNull(),
    outboxId: bigint('outbox_id', { mode: 'number' }).notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [check('outbox_relay_cursor_one_row', sql`${t.id} = 1`)]
);

/**
 * An upload is `pending` until the server has checked the stored object. With a malware
 * scanner configured (CLAMAV_URL) a confirmed upload is `scanning` until the worker's
 * `attachments.scan` job has scanned it: then `ready`, or `infected` (quarantined: the object is
 * kept but never served; `scan_result` names the signature).
 */
export const ATTACHMENT_STATUSES = ['pending', 'scanning', 'ready', 'infected'] as const;

/**
 * Files of attachment cells and form images. The server picks `storage_key` (`ws/<workspace>/...`, never
 * from the client) and only marks a row `ready` once the stored object's size matches `size`.
 * A file belongs to the base of the table it was uploaded to: record writes accept only ready
 * files of the same base, and downloads are authorized on a table of that base.
 */
export const attachments = pgTable(
  'attachments',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    tableId: uuid('table_id').notNull(),
    // The attachment field it was uploaded for, or (`view_id`) the form view whose cover or
    // logo it is: exactly one of the two.
    fieldId: uuid('field_id'),
    viewId: uuid('view_id'),
    // A file uploaded by a public form's submitter: the form link, and once submitted
    // the record it went into. Until then only that form's next submission may use it.
    shareId: uuid('share_id').references((): AnyPgColumn => shares.id, { onDelete: 'cascade' }),
    recordId: uuid('record_id'),
    // Not unique: a base restored from a snapshot shares the stored files of the
    // original, so the purge job deletes an object once no row names its key.
    storageKey: text('storage_key').notNull(),
    filename: text('filename').notNull(),
    contentType: text('content_type').notNull(),
    size: bigint('size', { mode: 'number' }).notNull(),
    status: text('status', { enum: ATTACHMENT_STATUSES }).notNull().default('pending'),
    width: integer('width'),
    height: integer('height'),
    thumbnailKey: text('thumbnail_key'),
    thumbnailSize: bigint('thumbnail_size', { mode: 'number' }),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    confirmedAt: timestamp('confirmed_at', { withTimezone: true }),
    // The malware scan: when it ran, and the signature of an infected file.
    scannedAt: timestamp('scanned_at', { withTimezone: true }),
    scanResult: text('scan_result'),
  },
  (t) => [
    index('attachments_workspace_id_idx').on(t.workspaceId),
    // The scan backlog the worker's sweep re-sends.
    index('attachments_scanning_idx').on(t.confirmedAt).where(sql`${t.status} = 'scanning'`),
    index('attachments_base_id_idx').on(t.baseId),
    index('attachments_storage_key_idx').on(t.storageKey),
    foreignKey({
      name: 'attachments_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
    foreignKey({
      name: 'attachments_table_fk',
      columns: [t.workspaceId, t.tableId],
      foreignColumns: [tables.workspaceId, tables.id],
    }).onDelete('cascade'),
    foreignKey({
      name: 'attachments_field_fk',
      columns: [t.workspaceId, t.fieldId],
      foreignColumns: [fields.workspaceId, fields.id],
    }).onDelete('cascade'),
    foreignKey({
      name: 'attachments_view_fk',
      columns: [t.workspaceId, t.viewId],
      foreignColumns: [views.workspaceId, views.id],
    }).onDelete('cascade'),
    check('attachments_owner_check', sql`(${t.fieldId} IS NULL) <> (${t.viewId} IS NULL)`),
    check('attachments_form_check', sql`${t.shareId} IS NULL OR ${t.fieldId} IS NOT NULL`),
    check(
      'attachments_status_check',
      sql`${t.status} IN ('pending', 'scanning', 'ready', 'infected')`
    ),
    check('attachments_size_check', sql`${t.size} > 0`),
  ]
);

/**
 * Comments on a record. Records live in the base's physical tables (ADR-001), so
 * `record_id` has no foreign key; routes only reach comments through the authorized table and a
 * live record of it. `body` is sanitized Markdown with mention tokens (`@[name](user:<id>)`),
 * `mentions` the user ids they name. Deleting is soft (`deleted_at`).
 */
export const recordComments = pgTable(
  'record_comments',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    tableId: uuid('table_id').notNull(),
    recordId: uuid('record_id').notNull(),
    authorId: uuid('author_id').references(() => users.id, { onDelete: 'set null' }),
    body: text('body').notNull(),
    mentions: uuid('mentions').array().notNull().default(sql`'{}'::uuid[]`),
    createdAt: createdAt(),
    editedAt: timestamp('edited_at', { withTimezone: true }),
    deletedAt: deletedAt(),
    deletedBy: uuid('deleted_by').references(() => users.id, { onDelete: 'set null' }),
  },
  (t) => [
    unique('record_comments_workspace_id_id_key').on(t.workspaceId, t.id),
    index('record_comments_workspace_id_idx').on(t.workspaceId),
    index('record_comments_record_idx').on(t.tableId, t.recordId, t.createdAt),
    foreignKey({
      name: 'record_comments_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
    foreignKey({
      name: 'record_comments_table_fk',
      columns: [t.workspaceId, t.tableId],
      foreignColumns: [tables.workspaceId, tables.id],
    }).onDelete('cascade'),
    check('record_comments_body_check', sql`char_length(${t.body}) BETWEEN 1 AND 10000`),
  ]
);

/** Emoji reactions to a comment: one row per comment, user and reaction. */
export const recordCommentReactions = pgTable(
  'record_comment_reactions',
  {
    workspaceId: uuid('workspace_id').notNull(),
    commentId: uuid('comment_id').notNull(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    reaction: text('reaction').notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    primaryKey({ columns: [t.commentId, t.userId, t.reaction] }),
    index('record_comment_reactions_workspace_id_idx').on(t.workspaceId),
    foreignKey({
      name: 'record_comment_reactions_comment_fk',
      columns: [t.workspaceId, t.commentId],
      foreignColumns: [recordComments.workspaceId, recordComments.id],
    }).onDelete('cascade'),
    check('record_comment_reactions_reaction_check', sql`char_length(${t.reaction}) <= 32`),
  ]
);

/**
 * Record revision history: one row per record change, written by the RecordService in the
 * change's transaction (the outbox is pruned after 7 days; this is the durable history).
 * `changes` maps field id to `{ type, before, after }` (API values; computed fields never
 * appear). Rapid edits of the same cells by the same actor coalesce into one row (`updated_at`
 * moves). Pruned past the retention (`record_revisions_prune`, the worker).
 */
export const recordRevisions = pgTable(
  'record_revisions',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    tableId: uuid('table_id').notNull(),
    recordId: uuid('record_id').notNull(),
    actorId: uuid('actor_id').references(() => users.id, { onDelete: 'set null' }),
    kind: text('kind', { enum: ['created', 'updated', 'deleted', 'restored'] }).notNull(),
    changes: jsonb('changes').notNull().default({}),
    clientOpId: text('client_op_id'),
    /**
     * How the change was made when no person made it: `form` (a public form), or
     * `automation` (an automation's step, `actor_id` the person it ran as).
     */
    via: text('via', { enum: ['form', 'automation'] }),
    /** The revision a restore brought back (no FK: it may be pruned first). */
    restoredFrom: uuid('restored_from'),
    createdAt: createdAt(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index('record_revisions_workspace_id_idx').on(t.workspaceId),
    index('record_revisions_record_idx').on(t.baseId, t.recordId, t.createdAt),
    index('record_revisions_created_at_idx').on(t.createdAt),
    foreignKey({
      name: 'record_revisions_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
    foreignKey({
      name: 'record_revisions_table_fk',
      columns: [t.workspaceId, t.tableId],
      foreignColumns: [tables.workspaceId, tables.id],
    }).onDelete('cascade'),
    check(
      'record_revisions_kind_check',
      sql`${t.kind} IN ('created', 'updated', 'deleted', 'restored')`
    ),
    check(
      'record_revisions_via_check',
      sql`${t.via} IS NULL OR ${t.via} IN ('form', 'automation')`
    ),
  ]
);

/**
 * Notifications: one row per recipient (`user_id`). Created in the transaction of the
 * write that caused them (a comment, a user cell), so they carry its workspace; RLS lets writers
 * insert into their workspace and only the recipient read, mark or delete them. `email_state`
 * drives the mailer: `pending` rows are emailed (coalesced per recipient and record, at most one
 * email per 10 minutes) or `skipped` (no access any more, preferences); `emailed_at` is when.
 */
export const notifications = pgTable(
  'notifications',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    actorId: uuid('actor_id').references(() => users.id, { onDelete: 'set null' }),
    kind: text('kind', { enum: ['mention', 'reply', 'assigned'] }).notNull(),
    baseId: uuid('base_id').notNull(),
    tableId: uuid('table_id').notNull(),
    recordId: uuid('record_id').notNull(),
    commentId: uuid('comment_id'),
    fieldId: uuid('field_id'),
    createdAt: createdAt(),
    readAt: timestamp('read_at', { withTimezone: true }),
    emailState: text('email_state', { enum: ['pending', 'sending', 'sent', 'skipped'] })
      .notNull()
      .default('pending'),
    emailedAt: timestamp('emailed_at', { withTimezone: true }),
  },
  (t) => [
    index('notifications_workspace_id_idx').on(t.workspaceId),
    index('notifications_user_idx').on(t.userId, t.createdAt),
    index('notifications_unread_idx').on(t.userId).where(sql`${t.readAt} IS NULL`),
    index('notifications_pending_idx').on(t.createdAt).where(sql`${t.emailState} = 'pending'`),
    index('notifications_emailed_idx').on(t.userId, t.recordId, t.emailedAt),
    foreignKey({
      name: 'notifications_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
    foreignKey({
      name: 'notifications_table_fk',
      columns: [t.workspaceId, t.tableId],
      foreignColumns: [tables.workspaceId, tables.id],
    }).onDelete('cascade'),
    foreignKey({
      name: 'notifications_comment_fk',
      columns: [t.workspaceId, t.commentId],
      foreignColumns: [recordComments.workspaceId, recordComments.id],
    }).onDelete('cascade'),
    check('notifications_kind_check', sql`${t.kind} IN ('mention', 'reply', 'assigned')`),
    check(
      'notifications_email_state_check',
      sql`${t.emailState} IN ('pending', 'sending', 'sent', 'skipped')`
    ),
  ]
);

/**
 * Public share links: a view (kind `view`) readable by anyone
 * holding the token. Only the token's SHA-256 (hex) is stored; the token is shown once. A link
 * answers until `revoked_at` or `expires_at`, and only while its view, table and base are live
 * and `created_by` may still share (`share_resolve` in drizzle/0026_shares_rls.sql).
 */
export const shares = pgTable(
  'shares',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    /**
     * `view` (one view), `base` (every table and non-personal view of the base) or `form`
     * (a form view to fill in).
     */
    kind: text('kind', { enum: ['view', 'base', 'form'] }).notNull(),
    /** The shared view (kinds `view` and `form`). */
    viewId: uuid('view_id'),
    tokenHash: text('token_hash').notNull(),
    /** The link's password as an argon2id PHC string, or null for none. */
    passwordHash: text('password_hash'),
    /** Bumped on every password change, so the unlock cookies of the old one stop working. */
    passwordVersion: integer('password_version').notNull().default(0),
    /** Viewers must sign in with a verified email at one of these domains; empty: anyone. */
    allowedDomains: text('allowed_domains').array().notNull().default(sql`'{}'::text[]`),
    /** The public page lets viewers select and copy cells (not enforceable: it shows the data). */
    allowCopy: boolean('allow_copy').notNull().default(true),
    /** Viewers may download a view as CSV (enforced by the server). */
    allowDownload: boolean('allow_download').notNull().default(false),
    /** Origins whose pages may frame the link's `/embed/<token>` page; empty: none. */
    embedOrigins: text('embed_origins').array().notNull().default(sql`'{}'::text[]`),
    /** Embedding is allowed even with a password or email domains (off by default). */
    allowRestrictedEmbed: boolean('allow_restricted_embed').notNull().default(false),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    expiresAt: timestamp('expires_at', { withTimezone: true }),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
  },
  (t) => [
    unique('shares_token_hash_unique').on(t.tokenHash),
    index('shares_view_id_idx').on(t.viewId),
    index('shares_base_id_idx').on(t.baseId),
    index('shares_workspace_id_idx').on(t.workspaceId),
    foreignKey({
      name: 'shares_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
    foreignKey({
      name: 'shares_view_fk',
      columns: [t.workspaceId, t.viewId],
      foreignColumns: [views.workspaceId, views.id],
    }).onDelete('cascade'),
    check('shares_kind_check', sql`${t.kind} IN ('view', 'base', 'form')`),
    check('shares_view_check', sql`(${t.kind} IN ('view', 'form')) = (${t.viewId} IS NOT NULL)`),
    check('shares_token_hash_check', sql`${t.tokenHash} ~ '^[0-9a-f]{64}$'`),
    // Only salted argon2id hashes, never a legacy unsalted digest (M2 review finding).
    check(
      'shares_password_hash_check',
      sql`${t.passwordHash} IS NULL OR ${t.passwordHash} LIKE '$argon2id$%'`
    ),
    check('shares_allowed_domains_check', sql`cardinality(${t.allowedDomains}) <= 20`),
    check('shares_embed_origins_check', sql`cardinality(${t.embedOrigins}) <= 20`),
  ]
);

/**
 * Public form submissions: one row per accepted submission, keyed by the submitter's
 * idempotency key (`submission_id`), so a double click or a retry of the same filled-in form
 * creates one record. Written in the submission's transaction.
 */
export const formSubmissions = pgTable(
  'form_submissions',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    shareId: uuid('share_id')
      .notNull()
      .references(() => shares.id, { onDelete: 'cascade' }),
    tableId: uuid('table_id').notNull(),
    recordId: uuid('record_id').notNull(),
    submissionId: uuid('submission_id').notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    unique('form_submissions_share_submission_unique').on(t.shareId, t.submissionId),
    index('form_submissions_workspace_id_idx').on(t.workspaceId),
    foreignKey({
      name: 'form_submissions_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
    foreignKey({
      name: 'form_submissions_table_fk',
      columns: [t.workspaceId, t.tableId],
      foreignColumns: [tables.workspaceId, tables.id],
    }).onDelete('cascade'),
  ]
);

/**
 * Base snapshots: one row per snapshot stored in object storage under `snapshots/`
 * (gzipped JSON lines: the schema, then records, link junctions and attachment references).
 * Rows are written once the object is complete; the worker deletes rows past the workspace's
 * retention (`base_snapshots_prune`) and then their objects.
 */
export const baseSnapshots = pgTable(
  'base_snapshots',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    baseName: text('base_name').notNull(),
    kind: text('kind', { enum: ['manual', 'auto'] }).notNull(),
    storageKey: text('storage_key').notNull(),
    size: bigint('size', { mode: 'number' }).notNull(),
    tableCount: integer('table_count').notNull(),
    recordCount: integer('record_count').notNull(),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
  },
  (t) => [
    unique('base_snapshots_storage_key_unique').on(t.storageKey),
    index('base_snapshots_base_id_idx').on(t.baseId, t.createdAt),
    index('base_snapshots_workspace_id_idx').on(t.workspaceId),
    foreignKey({
      name: 'base_snapshots_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
    check('base_snapshots_kind_check', sql`${t.kind} IN ('manual', 'auto')`),
  ]
);

/**
 * A base's webhooks: outbox events of the chosen kinds (and tables) are POSTed, signed, to
 * `url` by the worker. The signing secret is encrypted with the server's ENCRYPTION_KEY (it has
 * to be read back to sign); it is shown once, at creation and rotation.
 */
export const webhooks = pgTable(
  'webhooks',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    url: text('url').notNull(),
    description: text('description').notNull().default(''),
    /** Webhook event types (`WEBHOOK_EVENT_TYPES` in shared). */
    events: text('events').array().notNull(),
    /** Only these tables' events; null: every table. */
    tableIds: uuid('table_ids').array(),
    /** Record updates only when one of these fields changed; null: any field. */
    fieldIds: uuid('field_ids').array(),
    /** AES-256-GCM (auth/crypto.ts, purpose `webhook-secret`). */
    secretEncrypted: bytea('secret_encrypted').notNull(),
    /**
     * The secret before the last rotation, still signing deliveries until
     * `previous_secret_expires_at` (WEBHOOK_SECRET_GRACE_HOURS after the rotation); then ignored.
     */
    previousSecretEncrypted: bytea('previous_secret_encrypted'),
    previousSecretExpiresAt: timestamp('previous_secret_expires_at', { withTimezone: true }),
    enabled: boolean('enabled').notNull().default(true),
    /** Why the server turned it off: `failures` or `creator_access`; null otherwise. */
    disabledReason: text('disabled_reason'),
    /** Failed delivery attempts since the last success. */
    consecutiveFailures: integer('consecutive_failures').notNull().default(0),
    failingSince: timestamp('failing_since', { withTimezone: true }),
    lastDeliveryAt: timestamp('last_delivery_at', { withTimezone: true }),
    lastSuccess: boolean('last_success'),
    /** Whose access the payloads honour; a webhook whose creator is gone is disabled. */
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique('webhooks_workspace_id_id_unique').on(t.workspaceId, t.id),
    index('webhooks_base_id_idx').on(t.baseId),
    index('webhooks_workspace_id_idx').on(t.workspaceId),
    foreignKey({
      name: 'webhooks_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
    check('webhooks_events_check', sql`cardinality(${t.events}) > 0`),
    check(
      'webhooks_disabled_reason_check',
      sql`${t.disabledReason} IS NULL OR ${t.disabledReason} IN ('failures', 'creator_access')`
    ),
  ]
);

/** One delivery attempt of a webhook, kept 7 days (`webhook_deliveries_prune`). */
export const webhookDeliveries = pgTable(
  'webhook_deliveries',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    webhookId: uuid('webhook_id').notNull(),
    /** The `X-OpenRows-Event-Id`: the same for every attempt of one event. */
    eventId: text('event_id').notNull(),
    eventType: text('event_type').notNull(),
    outboxId: bigint('outbox_id', { mode: 'number' }),
    /** 1 for the first try. */
    attempt: integer('attempt').notNull(),
    success: boolean('success').notNull(),
    responseStatus: integer('response_status'),
    durationMs: integer('duration_ms').notNull(),
    /** The response body's start (WEBHOOK_RESPONSE_EXCERPT characters). */
    responseBody: text('response_body'),
    /** Why there was no response (refused address, timeout...). */
    error: text('error'),
    createdAt: createdAt(),
  },
  (t) => [
    index('webhook_deliveries_webhook_id_idx').on(t.webhookId, t.createdAt),
    index('webhook_deliveries_created_at_idx').on(t.createdAt),
    index('webhook_deliveries_workspace_id_idx').on(t.workspaceId),
    foreignKey({
      name: 'webhook_deliveries_webhook_fk',
      columns: [t.workspaceId, t.webhookId],
      foreignColumns: [webhooks.workspaceId, webhooks.id],
    }).onDelete('cascade'),
  ]
);

/**
 * Background jobs a person started and waits for: CSV imports, snapshot restores
 * , Airtable imports and base duplicates. The work runs in the worker on pg-boss (ADR-004); this row
 * is the state the requester reads (status, progress, error, result) and, for an import, its
 * input. The request inserts it and sends the pg-boss job in one transaction. `payload` (the CSV
 * text, or an Airtable import's encrypted token) is cleared when the job ends, and an Airtable
 * token after 24 hours at most (`jobs_sweep`); finished rows are pruned after 7 days.
 */
export const jobs = pgTable(
  'jobs',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    /** The table an import writes to. */
    tableId: uuid('table_id'),
    kind: text('kind', { enum: ['import', 'restore', 'airtable', 'duplicate'] }).notNull(),
    status: text('status', { enum: ['running', 'done', 'failed'] })
      .notNull()
      .default('running'),
    /** Who started it: the only one who may read it, and whose live role the work runs with. */
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'cascade' }),
    /** The checked request: an import's column plan, a restore's snapshot and name. */
    input: jsonb('input').notNull().default({}),
    /** An import's CSV text, or an Airtable import's encrypted token, until the job ends. */
    payload: text('payload'),
    /** Committed with each unit of work, so a retry resumes after the last one. */
    progress: jsonb('progress').notNull().default({}),
    result: jsonb('result'),
    error: text('error'),
    attempts: integer('attempts').notNull().default(0),
    createdAt: createdAt(),
    startedAt: timestamp('started_at', { withTimezone: true }),
    finishedAt: timestamp('finished_at', { withTimezone: true }),
  },
  (t) => [
    index('jobs_workspace_id_idx').on(t.workspaceId),
    index('jobs_finished_at_idx').on(t.finishedAt),
    // One running import per table.
    uniqueIndex('jobs_one_import_per_table')
      .on(t.tableId)
      .where(sql`${t.kind} = 'import' AND ${t.status} = 'running'`),
    foreignKey({
      name: 'jobs_workspace_fk',
      columns: [t.workspaceId],
      foreignColumns: [workspaces.id],
    }).onDelete('cascade'),
    foreignKey({
      name: 'jobs_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
    check('jobs_import_table_check', sql`${t.kind} <> 'import' OR ${t.tableId} IS NOT NULL`),
  ]
);

/**
 * An Airtable import's record map: each imported record's Airtable id and ours, with the
 * Airtable record ids its link cells named (`links`: our link field id → Airtable record ids).
 * The links pass reads it once every table's records are in, then the job deletes its rows (and
 * a deleted job takes them along).
 */
export const airtableImportRecords = pgTable(
  'airtable_import_records',
  {
    jobId: uuid('job_id')
      .notNull()
      .references(() => jobs.id, { onDelete: 'cascade' }),
    workspaceId: uuid('workspace_id').notNull(),
    airtableId: text('airtable_id').notNull(),
    tableId: uuid('table_id').notNull(),
    recordId: uuid('record_id').notNull(),
    links: jsonb('links'),
  },
  (t) => [
    primaryKey({ columns: [t.jobId, t.airtableId] }),
    index('airtable_import_records_table_idx').on(t.jobId, t.tableId, t.airtableId),
    index('airtable_import_records_workspace_id_idx').on(t.workspaceId),
    foreignKey({
      name: 'airtable_import_records_workspace_fk',
      columns: [t.workspaceId],
      foreignColumns: [workspaces.id],
    }).onDelete('cascade'),
  ]
);

/**
 * Stored objects whose row is gone: a trigger adds the keys of every deleted attachment
 * row (file and thumbnail) and base snapshot, cascades included (a purged base, table or field).
 * The attachment GC job deletes an object once no attachment row names its key and no snapshot
 * taken before the key got here is left (a restore would bring the file back), then the row.
 */
export const storageGarbage = pgTable(
  'storage_garbage',
  {
    id: bigint('id', { mode: 'number' }).primaryKey().generatedAlwaysAsIdentity(),
    workspaceId: uuid('workspace_id').notNull(),
    storageKey: text('storage_key').notNull(),
    /** `pending`: an upload never confirmed (in no snapshot); `file`; `snapshot`. */
    kind: text('kind', { enum: ['pending', 'file', 'snapshot'] }).notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    index('storage_garbage_workspace_idx').on(t.workspaceId, t.id),
    check('storage_garbage_kind_check', sql`${t.kind} IN ('pending', 'file', 'snapshot')`),
  ]
);

/**
 * A base's automations: a trigger (`trigger`, AutomationTrigger in shared) and ordered
 * actions, run by the worker as `created_by` with their live role. `trigger_type` and `table_id`
 * repeat the trigger for the outbox relay's matching (`automations_matching`); `armed_at` is
 * when it was last turned on or its trigger changed (older events don't trigger it);
 * `next_run_at` is a scheduled trigger's next run while it is on.
 */
export const automations = pgTable(
  'automations',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    name: text('name').notNull(),
    description: text('description').notNull().default(''),
    enabled: boolean('enabled').notNull().default(false),
    /** Why the server turned it off: `creator_access`; null otherwise. */
    disabledReason: text('disabled_reason'),
    trigger: jsonb('trigger').notNull(),
    actions: jsonb('actions').notNull().default([]),
    triggerType: text('trigger_type').notNull(),
    tableId: uuid('table_id'),
    armedAt: timestamp('armed_at', { withTimezone: true }).notNull().defaultNow(),
    nextRunAt: timestamp('next_run_at', { withTimezone: true }),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    lastRunAt: timestamp('last_run_at', { withTimezone: true }),
    lastRunStatus: text('last_run_status'),
    /**
     * The secret parts of the actions (secret HTTP header values, Slack webhook URLs),
     * encrypted as one JSON document; the `actions` column never holds them.
     */
    secretsEncrypted: bytea('secrets_encrypted'),
    /** A webhook-received trigger's URL token: its SHA-256 (hex) to look it up, ... */
    hookTokenHash: text('hook_token_hash'),
    /** ... and the token encrypted, so its creators can see the URL again. */
    hookTokenEncrypted: bytea('hook_token_encrypted'),
    /** The last request the hook received (its JSON body), to map fields from. */
    hookSample: jsonb('hook_sample'),
    hookSampleAt: timestamp('hook_sample_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique('automations_workspace_id_id_unique').on(t.workspaceId, t.id),
    uniqueIndex('automations_hook_token_hash_unique')
      .on(t.hookTokenHash)
      .where(sql`${t.hookTokenHash} IS NOT NULL`),
    index('automations_base_id_idx').on(t.baseId),
    index('automations_workspace_id_idx').on(t.workspaceId),
    index('automations_next_run_at_idx')
      .on(t.nextRunAt)
      .where(sql`${t.enabled} AND ${t.nextRunAt} IS NOT NULL`),
    foreignKey({
      name: 'automations_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
    check(
      'automations_trigger_type_check',
      sql`${t.triggerType} IN ('recordCreated', 'recordUpdated', 'recordMatches', 'scheduled', 'formSubmitted', 'webhookReceived', 'buttonClicked')`
    ),
    check(
      'automations_disabled_reason_check',
      sql`${t.disabledReason} IS NULL OR ${t.disabledReason} IN ('creator_access')`
    ),
    check(
      'automations_last_run_status_check',
      sql`${t.lastRunStatus} IS NULL OR ${t.lastRunStatus} IN ('succeeded', 'failed', 'skipped')`
    ),
  ]
);

/**
 * Interfaces: app-like pages on a base, built by its creators. RLS on `workspace_id`;
 * readers see an interface only through its published pages (the service filters by role).
 */
export const interfaces = pgTable(
  'interfaces',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    name: text('name').notNull(),
    position: doublePrecision('position').notNull().default(0),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique('interfaces_workspace_id_id_unique').on(t.workspaceId, t.id),
    index('interfaces_base_id_idx').on(t.baseId),
    foreignKey({
      name: 'interfaces_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
  ]
);

/**
 * A base's saved scripts, for the Scripts page: run in the browser's sandbox with the
 * runner's own permissions, never on the server. Creators write them, editors read and run them.
 */
export const baseScripts = pgTable(
  'base_scripts',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    name: text('name').notNull(),
    description: text('description').notNull().default(''),
    code: text('code').notNull().default(''),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    updatedBy: uuid('updated_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('base_scripts_base_id_idx').on(t.baseId),
    foreignKey({
      name: 'base_scripts_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
  ]
);

/**
 * A base's installed extensions: the extension panel, in `position` order. A built-in
 * (`built_in`, shared's BUILT_IN_EXTENSIONS) keeps its manifest here only for the record; its
 * manifest and bundle are always read from shared. A third-party one stores its `bundle`
 * (HTML, CSS, JS). `settings` belong to the installation (the extension's own JSON).
 */
export const baseExtensions = pgTable(
  'base_extensions',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    builtIn: text('built_in'),
    name: text('name').notNull(),
    manifest: jsonb('manifest').notNull(),
    bundle: jsonb('bundle'),
    settings: jsonb('settings').notNull().default({}),
    size: text('size').notNull().default('medium'),
    position: integer('position').notNull(),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    updatedBy: uuid('updated_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('base_extensions_base_id_idx').on(t.baseId),
    foreignKey({
      name: 'base_extensions_base_fk',
      columns: [t.workspaceId, t.baseId],
      foreignColumns: [bases.workspaceId, bases.id],
    }).onDelete('cascade'),
  ]
);

/**
 * A person's account at a sync connector (the hosted edition's Google Sheets), one per
 * connector: the OAuth tokens as one encrypted JSON document (`sync-connector-tokens`), never
 * returned. Syncs from a connector read with their creator's account; disconnecting revokes the
 * tokens at the provider and deletes the row, and those syncs pause at their next run. RLS: only
 * the owner's scope (app.user_id) reads or writes it.
 */
export const syncConnectorAccounts = pgTable(
  'sync_connector_accounts',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    connector: text('connector').notNull(),
    /** What the provider calls the account (an email address), shown to its owner. */
    label: text('label').notNull(),
    tokensEncrypted: bytea('tokens_encrypted').notNull(),
    createdAt: createdAt(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [unique('sync_connector_accounts_user_connector_unique').on(t.userId, t.connector)]
);

/**
 * A synced table's sync: one per table. The source can be in another workspace (the
 * creator's membership there is re-checked every run), so it is named by ids only; a run reads it
 * in the source's own tenant scope. `field_map` lists source field → this table's field; the
 * `source_field_id` field (type syncSource) holds each record's source key.
 */
export const tableSyncs = pgTable(
  'table_syncs',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    tableId: uuid('table_id').notNull(),
    /** `table`, `csv` or `postgres` (external: no source ids). */
    sourceKind: text('source_kind').notNull().default('table'),
    sourceWorkspaceId: uuid('source_workspace_id'),
    sourceBaseId: uuid('source_base_id'),
    sourceTableId: uuid('source_table_id'),
    sourceViewId: uuid('source_view_id'),
    /**
     * An external source's settings that aren't secret: a Postgres source's table or
     * query; `{}` otherwise.
     */
    sourceConfig: jsonb('source_config').notNull().default({}),
    /** An external source's URL or connection string, encrypted (`sync-source`). */
    sourceSecret: bytea('source_secret'),
    /** What the last good run saw: a CSV's ETag and Last-Modified, for conditional GETs. */
    sourceState: jsonb('source_state').notNull().default({}),
    /** An external source's key column; null: the row number (or a table source). */
    keyColumn: text('key_column'),
    /** "Base / Table / View" as of the last run. */
    sourceLabel: text('source_label').notNull().default(''),
    keyFieldId: uuid('key_field_id'),
    fieldMap: jsonb('field_map').notNull().default([]),
    sourceFieldId: uuid('source_field_id').notNull(),
    /** `manual`, `5m`, `hourly` or `daily` (SYNC_SCHEDULES). */
    schedule: text('schedule').notNull(),
    /** `active` or `paused` (then `pause_reason`, SYNC_PAUSE_REASONS). */
    status: text('status').notNull().default('active'),
    pauseReason: text('pause_reason'),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    lastSyncedAt: timestamp('last_synced_at', { withTimezone: true }),
    nextRunAt: timestamp('next_run_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique('table_syncs_workspace_id_id_unique').on(t.workspaceId, t.id),
    uniqueIndex('table_syncs_table_id_unique').on(t.tableId),
    index('table_syncs_base_id_idx').on(t.baseId),
    index('table_syncs_next_run_at_idx').on(t.nextRunAt),
    foreignKey({
      name: 'table_syncs_table_fk',
      columns: [t.workspaceId, t.tableId],
      foreignColumns: [tables.workspaceId, tables.id],
    }).onDelete('cascade'),
  ]
);

/**
 * A sync's runs: queued by "Sync now", the schedule or the sync's creation, then run by
 * the worker's `syncs.run`. The newest SYNC_RUN_HISTORY per sync are kept.
 */
export const tableSyncRuns = pgTable(
  'table_sync_runs',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    syncId: uuid('sync_id').notNull(),
    /** `create`, `manual` or `schedule`. */
    trigger: text('trigger').notNull(),
    /** `queued`, `running`, `succeeded`, `failed` or `paused`. */
    status: text('status').notNull().default('queued'),
    created: integer('created').notNull().default(0),
    updated: integer('updated').notNull().default(0),
    deleted: integer('deleted').notNull().default(0),
    unchanged: integer('unchanged').notNull().default(0),
    skipped: integer('skipped').notNull().default(0),
    error: text('error'),
    createdAt: createdAt(),
    startedAt: timestamp('started_at', { withTimezone: true }),
    finishedAt: timestamp('finished_at', { withTimezone: true }),
  },
  (t) => [
    index('table_sync_runs_sync_id_idx').on(t.syncId, t.createdAt),
    foreignKey({
      name: 'table_sync_runs_sync_fk',
      columns: [t.workspaceId, t.syncId],
      foreignColumns: [tableSyncs.workspaceId, tableSyncs.id],
    }).onDelete('cascade'),
  ]
);

/**
 * An interface's pages. `draft` is what its creators edit; `published` (a copy of the
 * draft when it was last published, null until then) is what everyone else sees. Both are
 * `interfacePageConfigSchema` in shared: the layout, table, filters and elements.
 */
export const interfacePages = pgTable(
  'interface_pages',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    interfaceId: uuid('interface_id').notNull(),
    name: text('name').notNull(),
    position: doublePrecision('position').notNull().default(0),
    draft: jsonb('draft').notNull(),
    published: jsonb('published'),
    publishedAt: timestamp('published_at', { withTimezone: true }),
    publishedBy: uuid('published_by').references(() => users.id, { onDelete: 'set null' }),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('interface_pages_interface_id_idx').on(t.interfaceId),
    index('interface_pages_workspace_id_idx').on(t.workspaceId),
    foreignKey({
      name: 'interface_pages_interface_fk',
      columns: [t.workspaceId, t.interfaceId],
      foreignColumns: [interfaces.workspaceId, interfaces.id],
    }).onDelete('cascade'),
  ]
);

/**
 * Interface-only collaborators: someone given one interface and not its base. The role
 * (`INTERFACE_ROLES`) counts on that interface only (`authz_resolve('interface', ...)`), never on
 * the base, its tables or other interfaces, so the base's API stays a 404 to them.
 */
export const interfaceMembers = pgTable(
  'interface_members',
  {
    workspaceId: uuid('workspace_id').notNull(),
    interfaceId: uuid('interface_id').notNull(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    role: text('role', { enum: INTERFACE_ROLES }).notNull(),
    invitedBy: uuid('invited_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    primaryKey({ columns: [t.interfaceId, t.userId] }),
    index('interface_members_user_id_idx').on(t.userId),
    index('interface_members_workspace_id_idx').on(t.workspaceId),
    foreignKey({
      name: 'interface_members_interface_fk',
      columns: [t.workspaceId, t.interfaceId],
      foreignColumns: [interfaces.workspaceId, interfaces.id],
    }).onDelete('cascade'),
    roleCheck('interface_members_role_check', INTERFACE_ROLES),
  ]
);

/**
 * One run of an automation, kept 30 days (`automation_runs_prune`): what triggered it,
 * each step's input, output and error. `idempotency_key` (`<outbox id>:<automation id>`,
 * `schedule:<time>`, `test:<id>` or `retry:<run id>`) makes a replayed relay batch or a
 * retried job run it once, and a failed run retried at most once.
 */
export const automationRuns = pgTable(
  'automation_runs',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    automationId: uuid('automation_id').notNull(),
    idempotencyKey: text('idempotency_key').notNull(),
    status: text('status', { enum: ['succeeded', 'failed', 'skipped'] }).notNull(),
    depth: smallint('depth').notNull(),
    trigger: jsonb('trigger').notNull().default({}),
    steps: jsonb('steps').notNull().default([]),
    error: text('error'),
    durationMs: integer('duration_ms').notNull().default(0),
    outboxId: bigint('outbox_id', { mode: 'number' }),
    /** Who started it: who clicked the button, tested or retried the run. */
    triggeredBy: uuid('triggered_by').references(() => users.id, { onDelete: 'set null' }),
    /**
     * How it started: `live` (its trigger fired), `test` (the builder's Test: not counted,
     * the automation's last run unchanged) or `retry` (a failed run started again).
     */
    mode: text('mode', { enum: ['live', 'test', 'retry'] })
      .notNull()
      .default('live'),
    /** A retry's failed run (no foreign key: runs are pruned, the retry's history stays). */
    retryOf: uuid('retry_of'),
    /**
     * Why a skipped run did nothing: `loop` (the loop guard) or `quota` (the workspace's
     * plan's monthly runs were used up); null otherwise.
     */
    skipReason: text('skip_reason', { enum: ['loop', 'quota'] }),
    createdAt: createdAt(),
  },
  (t) => [
    unique('automation_runs_idempotency_unique').on(t.automationId, t.idempotencyKey),
    index('automation_runs_automation_id_idx').on(t.automationId, t.createdAt),
    index('automation_runs_created_at_idx').on(t.createdAt),
    index('automation_runs_workspace_id_idx').on(t.workspaceId),
    foreignKey({
      name: 'automation_runs_automation_fk',
      columns: [t.workspaceId, t.automationId],
      foreignColumns: [automations.workspaceId, automations.id],
    }).onDelete('cascade'),
    check('automation_runs_status_check', sql`${t.status} IN ('succeeded', 'failed', 'skipped')`),
    check('automation_runs_mode_check', sql`${t.mode} IN ('live', 'test', 'retry')`),
    check(
      'automation_runs_skip_reason_check',
      sql`${t.skipReason} IS NULL OR ${t.skipReason} IN ('loop', 'quota')`
    ),
  ]
);

/**
 * The records matching a "record matches conditions" trigger: a record fires the
 * automation when it enters this set, not while it stays in it. Filled with the records already
 * matching when the automation is turned on or its trigger changes.
 */
export const automationMatches = pgTable(
  'automation_matches',
  {
    workspaceId: uuid('workspace_id').notNull(),
    automationId: uuid('automation_id').notNull(),
    recordId: uuid('record_id').notNull(),
  },
  (t) => [
    primaryKey({ name: 'automation_matches_pk', columns: [t.automationId, t.recordId] }),
    index('automation_matches_workspace_id_idx').on(t.workspaceId),
    foreignKey({
      name: 'automation_matches_automation_fk',
      columns: [t.workspaceId, t.automationId],
      foreignColumns: [automations.workspaceId, automations.id],
    }).onDelete('cascade'),
  ]
);

/** Automation runs per workspace and calendar month (UTC), for plan quotas later. */
export const automationRunCounts = pgTable(
  'automation_run_counts',
  {
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    /** The month's first day. */
    month: date('month').notNull(),
    runs: integer('runs').notNull().default(0),
  },
  (t) => [primaryKey({ name: 'automation_run_counts_pk', columns: [t.workspaceId, t.month] })]
);

/**
 * Live records (not in the trash) per user table: what a base's plan limit counts. Kept
 * by the RecordService in each write's transaction (inserts, trash and restore), recounted after
 * the writes that bypass it (duplicating a table, restoring a snapshot) and reconciled by the
 * worker's daily `usage.reconcile`.
 */
export const tableRecordCounts = pgTable(
  'table_record_counts',
  {
    workspaceId: uuid('workspace_id').notNull(),
    baseId: uuid('base_id').notNull(),
    tableId: uuid('table_id').notNull(),
    records: bigint('records', { mode: 'number' }).notNull().default(0),
    /** When the worker last recounted it. */
    reconciledAt: timestamp('reconciled_at', { withTimezone: true }),
  },
  (t) => [
    primaryKey({ name: 'table_record_counts_pk', columns: [t.tableId] }),
    index('table_record_counts_base_id_idx').on(t.baseId),
    foreignKey({
      name: 'table_record_counts_table_fk',
      columns: [t.workspaceId, t.tableId],
      foreignColumns: [tables.workspaceId, tables.id],
    }).onDelete('cascade'),
  ]
);

/**
 * REST API v1 requests per workspace and calendar month (UTC), for the plan's monthly quota
 * . Counted by the SECURITY DEFINER `api_call_count` once a request naming a base the
 * caller reaches is admitted (ratelimit/admission.ts); `personal_access_token_usage` counts per
 * token and user, not per workspace.
 */
export const apiCallCounts = pgTable(
  'api_call_counts',
  {
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    /** The month's first day. */
    month: date('month', { mode: 'string' }).notNull(),
    calls: bigint('calls', { mode: 'number' }).notNull().default(0),
  },
  (t) => [primaryKey({ name: 'api_call_counts_pk', columns: [t.workspaceId, t.month] })]
);

/**
 * AI credits per workspace and calendar month (UTC) on the instance's AI provider (the
 * hosted service's managed AI), for the plan's `aiCreditsPerMonth`. Counted by the SECURITY
 * DEFINER `ai_credit_count` after each answered request (ai/service.ts); requests on a
 * workspace's own key are never counted.
 */
export const aiCreditCounts = pgTable(
  'ai_credit_counts',
  {
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    /** The month's first day. */
    month: date('month', { mode: 'string' }).notNull(),
    credits: bigint('credits', { mode: 'number' }).notNull().default(0),
    /** Answered requests, for the operators' view of the credits' spread. */
    requests: bigint('requests', { mode: 'number' }).notNull().default(0),
    tokens: bigint('tokens', { mode: 'number' }).notNull().default(0),
  },
  (t) => [primaryKey({ name: 'ai_credit_counts_pk', columns: [t.workspaceId, t.month] })]
);

/**
 * Plan-limit warning emails sent to a workspace's owners: one per limit (and base, for
 * records per base), level and month. The worker's `usage.warnings` inserts the row in the same
 * transaction as the send, so a failed send is retried and a sent one never repeats.
 */
export const usageWarningsSent = pgTable(
  'usage_warnings_sent',
  {
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    /** A UsageWarningMetric. */
    metric: text('metric').notNull(),
    /** The base of a records-per-base warning; '' for a workspace-wide limit. */
    subject: text('subject').notNull().default(''),
    /** `near` (80%) or `full` (100%). */
    level: text('level').notNull(),
    /** The month's first day (UTC). */
    month: date('month', { mode: 'string' }).notNull(),
    sentAt: timestamp('sent_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    primaryKey({
      name: 'usage_warnings_sent_pk',
      columns: [t.workspaceId, t.metric, t.subject, t.level, t.month],
    }),
  ]
);

/**
 * Emails automations sent per workspace and UTC day, one per recipient: the daily cap
 * (`AUTOMATION_EMAIL_DAILY_LIMIT`) is taken from here before a send.
 */
export const automationEmailCounts = pgTable(
  'automation_email_counts',
  {
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    day: date('day').notNull(),
    sent: integer('sent').notNull().default(0),
  },
  (t) => [primaryKey({ name: 'automation_email_counts_pk', columns: [t.workspaceId, t.day] })]
);

/**
 * Tables in `public` without a `workspace_id` column (ADR-002). `workspaces` is the tenant root:
 * its own `id` is the workspace id; personal access tokens belong to a user, under an
 * owner policy, like their usage counters; the API's rate limit buckets are keyed by base,
 * token or user, the outbound concurrency slots by key; the outbox relay's cursor is
 * one global row. Every other table must be tenant-owned; a test checks.
 */
/**
 * A workspace's subscriptions at the billing provider, written only from the provider's
 * signed events (`src/billing/store.ts`). `entitled` subscriptions decide the workspace's plan;
 * `changed_at` is the provider's version of the subscription, so an older event never overwrites
 * a newer one. One row per provider subscription across every workspace.
 */
export const billingSubscriptions = pgTable(
  'billing_subscriptions',
  {
    id: uuid('id').primaryKey().$defaultFn(uuidv7),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    provider: text('provider').notNull(),
    subscriptionId: text('subscription_id').notNull(),
    customerId: text('customer_id').notNull(),
    plan: text('plan').notNull(),
    /** `month` or `year`. */
    interval: text('interval').notNull(),
    /** A SubscriptionStatus. */
    status: text('status').notNull(),
    entitled: boolean('entitled').notNull(),
    cancelAtPeriodEnd: boolean('cancel_at_period_end').notNull().default(false),
    currentPeriodEnd: timestamp('current_period_end', { withTimezone: true }),
    changedAt: timestamp('changed_at', { withTimezone: true, precision: 6 }).notNull(),
    /**
     * Seats billed: the provider's count from its events, or the count the seat sync last
     * set; null for a subscription without seats (a flat price).
     */
    seats: integer('seats'),
    /** When the seat sync last set `seats` at the provider. */
    seatsSyncedAt: timestamp('seats_synced_at', { withTimezone: true }),
    /**
     * Dunning: when the subscription went `past_due` (null otherwise). The plan stays for
     * BILLING_GRACE_DAYS from then; afterwards `entitled` turns false and the default plan applies.
     */
    pastDueSince: timestamp('past_due_since', { withTimezone: true }),
    /** Dunning emails sent for this `past_due` spell: 0 none, 1 failed, 2 reminder, 3 ended. */
    dunningStage: smallint('dunning_stage').notNull().default(0),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex('billing_subscriptions_provider_id_uq').on(t.provider, t.subscriptionId),
    index('billing_subscriptions_workspace_idx').on(t.workspaceId),
  ]
);

/**
 * Billing provider events already received, by the provider's event id (Standard
 * Webhooks' `webhook-id`): each is applied once. Global (an event may name no workspace); the
 * app role reaches it only through `billing_event_claim` and `billing_event_settle`.
 */
export const billingEvents = pgTable(
  'billing_events',
  {
    provider: text('provider').notNull(),
    eventId: text('event_id').notNull(),
    type: text('type').notNull(),
    /** `applied`, `ignored`, `stale` or `unmatched`. */
    outcome: text('outcome').notNull().default('pending'),
    /** The workspace it changed, when it named one (no foreign key: the log outlives it). */
    subjectWorkspaceId: uuid('subject_workspace_id'),
    receivedAt: timestamp('received_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ name: 'billing_events_pk', columns: [t.provider, t.eventId] }),
    index('billing_events_received_idx').on(t.receivedAt),
  ]
);

/**
 * The ops console's append-only audit log: one entry per system admin request. Global, not
 * tenant data (the targets are plain ids, so purges never touch it). The app role may only
 * INSERT and SELECT, under RLS: system admins see and write every entry, a user sees the entries
 * that name them (their account activity); a trigger refuses UPDATE, DELETE and TRUNCATE to
 * every role (0080_admin_console_rls.sql).
 */
export const adminAuditLog = pgTable(
  'admin_audit_log',
  {
    id: id(),
    adminId: uuid('admin_id').notNull(),
    action: text('action').notNull(),
    targetUserId: uuid('target_user_id'),
    targetWorkspaceId: uuid('target_workspace_id'),
    detail: jsonb('detail').notNull().default({}),
    ip: inet('ip'),
    createdAt: createdAt(),
  },
  (t) => [
    index('admin_audit_log_created_idx').on(t.createdAt),
    index('admin_audit_log_target_user_idx').on(t.targetUserId, t.createdAt),
    index('admin_audit_log_target_workspace_idx').on(t.targetWorkspaceId, t.createdAt),
  ]
);

/**
 * Service notices: Terms, privacy, price and plan changes the operator announces by email
 * (the `notices` command, src/notices/cli.ts) and as a banner in the app. Global, like `users`:
 * signed-in users read them (RLS `read`); they are written only through `legal_notice_create`
 * and `legal_notice_withdraw` (drizzle/0082_legal_notices_rls.sql).
 */
export const legalNotices = pgTable(
  'legal_notices',
  {
    id: id(),
    kind: text('kind').notNull(),
    audience: text('audience').notNull(),
    title: text('title').notNull(),
    summary: text('summary').notNull(),
    url: text('url').notNull(),
    effectiveAt: timestamp('effective_at', { withTimezone: true }).notNull(),
    publishedAt: timestamp('published_at', { withTimezone: true }).notNull().defaultNow(),
    withdrawnAt: timestamp('withdrawn_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    check(
      'legal_notices_kind_check',
      sql`${t.kind} IN ('terms', 'privacy', 'price', 'plan', 'service')`
    ),
    check('legal_notices_audience_check', sql`${t.audience} IN ('everyone', 'owners')`),
    index('legal_notices_effective_idx').on(t.effectiveAt),
  ]
);

/** Who dismissed a notice's banner: the user's own rows (RLS `self`). */
export const legalNoticeDismissals = pgTable(
  'legal_notice_dismissals',
  {
    noticeId: uuid('notice_id')
      .notNull()
      .references(() => legalNotices.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    dismissedAt: timestamp('dismissed_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.noticeId, t.userId] })]
);

/**
 * The notice command's log: one row per account a notice was emailed to, with the run that
 * sent it, so a run that stopped half way resumes without emailing anyone twice. Written only by
 * `legal_notice_delivered`; users read their own (RLS `self_read`).
 */
export const legalNoticeDeliveries = pgTable(
  'legal_notice_deliveries',
  {
    noticeId: uuid('notice_id')
      .notNull()
      .references(() => legalNotices.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    runId: uuid('run_id').notNull(),
    sentAt: timestamp('sent_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.noticeId, t.userId] }),
    index('legal_notice_deliveries_run_idx').on(t.noticeId, t.runId),
  ]
);

/**
 * A workspace's own AI provider: an OpenAI-compatible endpoint, a model and the owner's
 * API key, encrypted (AES-256-GCM, the `ai-key` purpose of ENCRYPTION_KEY). Without a row AI
 * features use the instance's provider (AI_*), or are off. The key is never read back out.
 */
export const workspaceAiSettings = pgTable('workspace_ai_settings', {
  workspaceId: uuid('workspace_id')
    .primaryKey()
    .references(() => workspaces.id, { onDelete: 'cascade' }),
  baseUrl: text('base_url').notNull(),
  model: text('model').notNull(),
  apiKeyEncrypted: bytea('api_key_encrypted').notNull(),
  updatedBy: uuid('updated_by').references(() => users.id, { onDelete: 'set null' }),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/**
 * AI fields' per-record generation state: `pending` (waiting for the worker's
 * `ai.generate`, requested at `requested_at`), `done`, `error` (with the message shown in the
 * cell; the value is kept) or `canceled`. The value itself is in the record's column. A row is
 * written when a cell is first requested; records deleted since are dropped by the job.
 */
export const aiFieldCells = pgTable(
  'ai_field_cells',
  {
    workspaceId: uuid('workspace_id').notNull(),
    fieldId: uuid('field_id').notNull(),
    recordId: uuid('record_id').notNull(),
    status: text('status', { enum: ['pending', 'done', 'error', 'canceled'] }).notNull(),
    error: text('error'),
    requestedAt: timestamp('requested_at', { withTimezone: true, precision: 3 })
      .notNull()
      .defaultNow(),
    updatedAt: updatedAt(),
  },
  (t) => [
    primaryKey({ columns: [t.fieldId, t.recordId] }),
    index('ai_field_cells_status_idx').on(t.fieldId, t.status, t.requestedAt),
    index('ai_field_cells_workspace_id_idx').on(t.workspaceId),
    foreignKey({
      name: 'ai_field_cells_field_fk',
      columns: [t.workspaceId, t.fieldId],
      foreignColumns: [fields.workspaceId, fields.id],
    }).onDelete('cascade'),
    check(
      'ai_field_cells_status_check',
      sql`${t.status} IN ('pending', 'done', 'error', 'canceled')`
    ),
  ]
);

export const GLOBAL_TABLES = [
  'admin_audit_log',
  'users',
  'sessions',
  'workspaces',
  'personal_access_tokens',
  'personal_access_token_usage',
  'oauth_apps',
  'oauth_authorizations',
  'oauth_codes',
  'oauth_tokens',
  'sync_connector_accounts',
  'rate_limit_buckets',
  'outbound_leases',
  'outbox_relay_cursor',
  'billing_events',
  'legal_notices',
  'legal_notice_dismissals',
  'legal_notice_deliveries',
] as const;

/**
 * Tables without row-level security: global, not tenant data (the app role can't touch
 * `rate_limit_buckets` or `outbox_relay_cursor` at all, only their functions). Every other table
 * in `public` must have RLS enabled and forced, with at least one policy; a migration test checks.
 */
export const RLS_EXEMPT_TABLES = [
  'users',
  'sessions',
  'rate_limit_buckets',
  'outbound_leases',
  'outbox_relay_cursor',
  'billing_events',
] as const;

/**
 * The workspace audit log: one row per recorded action, written through the edition's
 * AuditSink (nothing in the OSS edition; the hosted edition on plans with the audit log). Append-only:
 * the app role may only insert and read (RLS, its workspace), a trigger refuses every UPDATE and
 * any DELETE but `workspace_audit_purge`'s (retention, 0097_workspace_audit_rls.sql). No foreign
 * key to the workspace, so purging a workspace never needs to delete its log; the retention job
 * drops a purged workspace's entries. `summary` holds a short before/after of names and settings,
 * never secrets or cell values (sanitizeAuditValues).
 */
export const workspaceAuditEvents = pgTable(
  'workspace_audit_events',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    action: text('action').notNull(),
    actorKind: text('actor_kind', { enum: ['user', 'token', 'admin', 'system', 'scim'] }).notNull(),
    actorId: uuid('actor_id'),
    actorEmail: text('actor_email'),
    ip: inet('ip'),
    userAgent: text('user_agent'),
    targetType: text('target_type').notNull(),
    targetId: text('target_id'),
    targetName: text('target_name'),
    summary: jsonb('summary').notNull().default({}),
    createdAt: createdAt(),
  },
  (t) => [
    index('workspace_audit_events_workspace_idx').on(t.workspaceId, t.id),
    index('workspace_audit_events_action_idx').on(t.workspaceId, t.action, t.id),
    index('workspace_audit_events_actor_idx').on(t.workspaceId, t.actorId, t.id),
  ]
);

/**
 * A workspace's SIEM stream of its audit log: new entries POSTed in batches to `url`,
 * signed with the encrypted secret (`audit-stream`), from `cursor` (the last delivered entry's
 * id) on. Turned off after AUDIT_STREAM_MAX_FAILURES failed deliveries in a row.
 */
export const workspaceAuditStreams = pgTable('workspace_audit_streams', {
  workspaceId: uuid('workspace_id')
    .primaryKey()
    .references(() => workspaces.id, { onDelete: 'cascade' }),
  url: text('url').notNull(),
  secretEncrypted: bytea('secret_encrypted').notNull(),
  enabled: boolean('enabled').notNull().default(true),
  cursor: uuid('cursor'),
  lastDeliveryAt: timestamp('last_delivery_at', { withTimezone: true }),
  lastError: text('last_error'),
  failures: integer('failures').notNull().default(0),
  createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/**
 * A workspace's policies (the hosted admin console): share links, public forms, embeds,
 * personal access tokens and invitation domains (shared's `WorkspacePolicies`). No row: the
 * defaults, which allow everything. `authz_resolve` and `share_resolve` read it, so every
 * request sees a change at once.
 */
export const workspacePolicies = pgTable('workspace_policies', {
  workspaceId: uuid('workspace_id')
    .primaryKey()
    .references(() => workspaces.id, { onDelete: 'cascade' }),
  shareLinks: boolean('share_links').notNull().default(true),
  publicForms: boolean('public_forms').notNull().default(true),
  embeds: boolean('embeds').notNull().default(true),
  personalAccessTokens: boolean('personal_access_tokens').notNull().default(true),
  inviteDomains: text('invite_domains').array().notNull().default(sql`'{}'::text[]`),
  updatedBy: uuid('updated_by').references(() => users.id, { onDelete: 'set null' }),
  updatedAt: updatedAt(),
});

/**
 * When each person last used a workspace's data (the admin console's member list): touched
 * by `withResource` at most every ACTIVITY_TOUCH_MINUTES per person and workspace, for signed-in
 * sessions and personal access tokens alike (never an impersonating admin).
 */
export const workspaceMemberActivity = pgTable(
  'workspace_member_activity',
  {
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    lastActiveAt: timestamp('last_active_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.workspaceId, t.userId] })]
);

/**
 * A workspace's single sign-on connection (hosted edition): one SAML or OIDC identity
 * provider, set up in Keycloak as the identity provider `alias` (brokering). `config` holds what
 * isn't secret (issuer, client id and endpoints, or entity id, SSO URL and certificates); the
 * OIDC client secret lives in Keycloak only.
 */
export const workspaceSsoConnections = pgTable('workspace_sso_connections', {
  workspaceId: uuid('workspace_id')
    .primaryKey()
    .references(() => workspaces.id, { onDelete: 'cascade' }),
  alias: text('alias').notNull().unique(),
  protocol: text('protocol', { enum: ['oidc', 'saml'] }).notNull(),
  displayName: text('display_name').notNull(),
  config: jsonb('config').$type<Record<string, unknown>>().notNull(),
  enabled: boolean('enabled').notNull().default(true),
  requireSso: boolean('require_sso').notNull().default(false),
  jit: boolean('jit').notNull().default(true),
  defaultRole: text('default_role', { enum: ['creator', 'editor', 'commenter', 'read_only'] })
    .notNull()
    .default('editor'),
  createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/**
 * The email domains of a workspace's single sign-on, each proved by a DNS TXT record with
 * its token. A domain counts once verified, and only one workspace can have it verified.
 */
export const workspaceSsoDomains = pgTable(
  'workspace_sso_domains',
  {
    id: uuid('id').primaryKey(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    domain: text('domain').notNull(),
    token: text('token').notNull(),
    verifiedAt: timestamp('verified_at', { withTimezone: true }),
    lastCheckedAt: timestamp('last_checked_at', { withTimezone: true }),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
  },
  (t) => [
    unique('workspace_sso_domains_workspace_domain').on(t.workspaceId, t.domain),
    uniqueIndex('workspace_sso_domains_verified_idx')
      .on(t.domain)
      .where(sql`${t.verifiedAt} IS NOT NULL`),
  ]
);

/** The roles SCIM provisioning gives: never owner (owners are managed in OpenRows). */
const SCIM_ROLES = ['creator', 'editor', 'commenter', 'read_only'] as const;

/**
 * A workspace's SCIM provisioning (hosted edition): the bearer token the identity provider
 * calls `/scim/v2` with, stored as its SHA-256 (null once revoked; rotating replaces it), and the
 * role provisioned people get when none of their groups maps to one.
 */
export const workspaceScimSettings = pgTable('workspace_scim_settings', {
  workspaceId: uuid('workspace_id')
    .primaryKey()
    .references(() => workspaces.id, { onDelete: 'cascade' }),
  tokenHash: text('token_hash').unique(),
  // The token's last 4 characters, to tell tokens apart in the settings.
  tokenHint: text('token_hint'),
  tokenCreatedAt: timestamp('token_created_at', { withTimezone: true }),
  lastUsedAt: timestamp('last_used_at', { withTimezone: true }),
  defaultRole: text('default_role', { enum: SCIM_ROLES }).notNull().default('editor'),
  createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/**
 * A SCIM User of a workspace: the identity provider's person, linked to the OpenRows
 * account with the same verified address (`user_id`, set when it exists or at their first
 * sign-in). While `active`, the account is a member with the role of its groups (or the default).
 */
export const workspaceScimUsers = pgTable(
  'workspace_scim_users',
  {
    id: uuid('id').primaryKey(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    userName: text('user_name').notNull(),
    externalId: text('external_id'),
    // Lower-cased, on one of the workspace's verified single sign-on domains.
    email: text('email').notNull(),
    givenName: text('given_name'),
    familyName: text('family_name'),
    displayName: text('display_name'),
    active: boolean('active').notNull().default(true),
    userId: uuid('user_id').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('workspace_scim_users_user_name_idx').on(t.workspaceId, sql`lower(${t.userName})`),
    uniqueIndex('workspace_scim_users_email_idx').on(t.workspaceId, t.email),
    uniqueIndex('workspace_scim_users_user_idx').on(t.workspaceId, t.userId),
    index('workspace_scim_users_pending_idx').on(t.email).where(sql`${t.userId} IS NULL`),
  ]
);

/** A SCIM Group of a workspace; `role`, set by the workspace's owners, maps it to a role. */
export const workspaceScimGroups = pgTable(
  'workspace_scim_groups',
  {
    id: uuid('id').primaryKey(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    displayName: text('display_name').notNull(),
    externalId: text('external_id'),
    role: text('role', { enum: SCIM_ROLES }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('workspace_scim_groups_name_idx').on(t.workspaceId, sql`lower(${t.displayName})`),
  ]
);

/** The SCIM Users in a SCIM Group. */
export const workspaceScimGroupMembers = pgTable(
  'workspace_scim_group_members',
  {
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    groupId: uuid('group_id')
      .notNull()
      .references(() => workspaceScimGroups.id, { onDelete: 'cascade' }),
    scimUserId: uuid('scim_user_id')
      .notNull()
      .references(() => workspaceScimUsers.id, { onDelete: 'cascade' }),
  },
  (t) => [
    primaryKey({ columns: [t.groupId, t.scimUserId] }),
    index('workspace_scim_group_members_user_idx').on(t.scimUserId),
  ]
);
